--
-- Name: candidate_documents; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.candidate_documents ENABLE ROW LEVEL SECURITY;

--
-- Name: candidate_documents candidate_documents_tenant_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidate_documents_tenant_select ON public.candidate_documents FOR SELECT TO authenticated USING ((security.is_org_member(org_id) OR (EXISTS ( SELECT 1
   FROM public.hiring_runs hr
  WHERE ((hr.id = candidate_documents.hiring_run_id) AND (hr.employer_id = auth.uid()))))));


--
-- Name: candidate_profiles; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.candidate_profiles ENABLE ROW LEVEL SECURITY;

--
-- Name: candidate_profiles candidate_profiles_self_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidate_profiles_self_insert ON public.candidate_profiles FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));


--
-- Name: candidate_profiles candidate_profiles_self_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidate_profiles_self_select ON public.candidate_profiles FOR SELECT TO authenticated USING (((auth.uid() = id) OR (EXISTS ( SELECT 1
   FROM (public.candidates c
     JOIN public.hiring_runs h ON ((c.hiring_run_id = h.id)))
  WHERE ((c.candidate_id = candidate_profiles.id) AND ((h.employer_id = auth.uid()) OR ((h.org_id IS NOT NULL) AND security.is_org_member(h.org_id))))))));


--
-- Name: candidate_profiles candidate_profiles_self_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidate_profiles_self_update ON public.candidate_profiles FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));


--
-- Name: candidates; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.candidates ENABLE ROW LEVEL SECURITY;

--
-- Name: candidates candidates_org_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidates_org_select ON public.candidates FOR SELECT TO authenticated USING (security.is_hiring_run_member(hiring_run_id));


--
-- Name: candidates candidates_org_write; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidates_org_write ON public.candidates TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.hiring_runs h
  WHERE ((h.id = candidates.hiring_run_id) AND ((h.employer_id = auth.uid()) OR ((h.org_id IS NOT NULL) AND security.has_org_role(h.org_id, ARRAY['owner'::text, 'admin'::text, 'recruiter'::text, 'hiring_manager'::text]))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.hiring_runs h
  WHERE ((h.id = candidates.hiring_run_id) AND ((h.employer_id = auth.uid()) OR ((h.org_id IS NOT NULL) AND security.has_org_role(h.org_id, ARRAY['owner'::text, 'admin'::text, 'recruiter'::text, 'hiring_manager'::text])))))));


--
-- Name: candidates candidates_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY candidates_select ON public.candidates FOR SELECT TO authenticated USING (((candidate_id = auth.uid()) OR security.is_hiring_run_member(hiring_run_id)));


