--
-- Name: hiring_runs hiring_runs_org_write; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY hiring_runs_org_write ON public.hiring_runs TO authenticated USING (((auth.uid() = employer_id) OR ((org_id IS NOT NULL) AND security.has_org_role(org_id, ARRAY['owner'::text, 'admin'::text, 'recruiter'::text])))) WITH CHECK (((auth.uid() = employer_id) OR ((org_id IS NOT NULL) AND security.has_org_role(org_id, ARRAY['owner'::text, 'admin'::text, 'recruiter'::text]))));


--
-- Name: organization_memberships org_memberships_delete; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY org_memberships_delete ON public.organization_memberships FOR DELETE TO authenticated USING ((security.has_org_role(organization_id, ARRAY['owner'::text]) OR (security.has_org_role(organization_id, ARRAY['admin'::text]) AND (( SELECT m.membership_role
   FROM public.organization_memberships m
  WHERE ((m.organization_id = organization_memberships.organization_id) AND (m.user_id = organization_memberships.user_id))) <> 'owner'::text))));


--
-- Name: organization_memberships org_memberships_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY org_memberships_insert ON public.organization_memberships FOR INSERT TO authenticated WITH CHECK ((security.has_org_role(organization_id, ARRAY['owner'::text]) OR (security.has_org_role(organization_id, ARRAY['admin'::text]) AND (membership_role <> 'owner'::text)) OR ((user_id = auth.uid()) AND (membership_role = 'owner'::text))));


--
-- Name: organization_memberships org_memberships_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY org_memberships_select ON public.organization_memberships FOR SELECT TO authenticated USING ((security.is_org_member(organization_id) OR (user_id = auth.uid())));


--
-- Name: organization_memberships org_memberships_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY org_memberships_update ON public.organization_memberships FOR UPDATE TO authenticated USING ((security.has_org_role(organization_id, ARRAY['owner'::text]) OR (security.has_org_role(organization_id, ARRAY['admin'::text]) AND (( SELECT m.membership_role
   FROM public.organization_memberships m
  WHERE ((m.organization_id = organization_memberships.organization_id) AND (m.user_id = organization_memberships.user_id))) <> 'owner'::text)))) WITH CHECK ((security.has_org_role(organization_id, ARRAY['owner'::text]) OR (security.has_org_role(organization_id, ARRAY['admin'::text]) AND (membership_role <> 'owner'::text) AND (( SELECT m.membership_role
   FROM public.organization_memberships m
  WHERE ((m.organization_id = organization_memberships.organization_id) AND (m.user_id = organization_memberships.user_id))) <> 'owner'::text))));


